-- GASP dataset ticket (event; Support ticket). rows dated from 2025-12-01
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.ticket (
  agent_id VARCHAR(1000),
  created_at TIMESTAMP,
  customer_id VARCHAR(1000),
  escalated BOOLEAN,
  first_response_at TIMESTAMP,
  first_response_due_at TIMESTAMP,
  reopened BOOLEAN,
  resolution_due_at TIMESTAMP,
  resolved_at TIMESTAMP,
  resolved_first_contact BOOLEAN,
  ticket_id VARCHAR(1000),
  ticket_status VARCHAR(1000),
  ticket_type VARCHAR(1000)
);
